insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Problem solving', 'Problem solving is the process of achieving a goal by overcoming obstacles, a frequent part of most activities. Problems in need of solutions range from simple personal tasks (e.g. how to get from point A to B) to complex issues in business and technical fields. The former is an example of simple problem solving (SPS) addressing one issue, whereas the latter is complex problem solving (CPS) with multiple interrelated obstacles. Another classification of problem-solving tasks is into well-defined problems with specific obstacles and goals, and ill-defined problems in which the current situation is troublesome but it is not clear what kind of resolution to aim for. Similarly, one may distinguish formal or fact-based problems requiring psychometric intelligence, versus socio-emotional problems which depend on the changeable emotions of individuals or groups, such as tactful behavior, fashion, or gift choices. Solutions require sufficient resources and knowledge to attain the goal. Professionals such as lawyers, doctors, programmers, and consultants are largely problem solvers for issues that require technical skills and knowledge beyond general competence. Many businesses have found profitable markets by recognizing a problem and creating a solution: the more widespread and inconvenient the problem, the greater the opportunity to develop a scalable solution.', 'Wikipedia: Problem solving', 'https://en.wikipedia.org/w/index.php?title=Problem_solving&oldid=1378905256', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Problem solving is the process of achieving a goal by overcoming obstacles, a frequent part of most activities. Problems in need of solutions range from simple personal tasks (e.g. how to get from point A to B) to complex issues in business and technical fields. The former is an example of simple problem solving (SPS) addressing one issue, whereas the latter is complex problem solving (CPS) with multiple interrelated obstacles. Another classification of problem-solving tasks is into well-defined problems with specific obstacles and goals, and ill-defined problems in which the current situation is troublesome but it is not clear what kind of resolution to aim for. Similarly, one may distinguish formal or fact-based problems requiring psychometric intelligence, versus socio-emotional problems which depend on the changeable emotions of individuals or groups, such as tactful behavior, fashion, or gift choices. Solutions require sufficient resources and knowledge to attain the goal. Professionals such as lawyers, doctors, programmers, and consultants are largely problem solvers for issues that require technical skills and knowledge beyond general competence. Many businesses have found profitable markets by recognizing a problem and creating a solution: the more widespread and inconvenient the problem, the greater the opportunity to develop a scalable solution.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Problem solving', 'There are many specialized problem-solving techniques and methods in fields such as science, engineering, business, medicine, mathematics, computer science, philosophy, and social organization. The mental techniques to identify, analyze, and solve problems are studied in psychology and cognitive sciences. Also widely researched are the mental obstacles that prevent people from finding solutions; problem-solving impediments include confirmation bias, mental set, and functional fixedness.', 'Wikipedia: Problem solving', 'https://en.wikipedia.org/w/index.php?title=Problem_solving&oldid=1378905256', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'There are many specialized problem-solving techniques and methods in fields such as science, engineering, business, medicine, mathematics, computer science, philosophy, and social organization. The mental techniques to identify, analyze, and solve problems are studied in psychology and cognitive sciences. Also widely researched are the mental obstacles that prevent people from finding solutions; problem-solving impediments include confirmation bias, mental set, and functional fixedness.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Problem solving: Definition', 'The term problem solving has a slightly different meaning depending on the discipline. For instance, it is a mental process in psychology and a computerized process in computer science. There are two different types of problems: ill-defined and well-defined; different approaches are used for each. Well-defined problems have specific end goals and clearly expected solutions, while ill-defined problems do not. Well-defined problems allow for more initial planning than ill-defined problems. Solving problems sometimes involves dealing with pragmatics (the way that context contributes to meaning) and semantics (the interpretation of the problem). The ability to understand what the end goal of the problem is, and what rules could be applied, represents the key to solving the problem. Sometimes a problem requires abstract thinking or coming up with a creative solution. Problem solving has two major domains: mathematical problem solving and personal problem solving. Each concerns some difficulty or barrier that is encountered.', 'Wikipedia: Problem solving', 'https://en.wikipedia.org/w/index.php?title=Problem_solving&oldid=1378905256', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'The term problem solving has a slightly different meaning depending on the discipline. For instance, it is a mental process in psychology and a computerized process in computer science. There are two different types of problems: ill-defined and well-defined; different approaches are used for each. Well-defined problems have specific end goals and clearly expected solutions, while ill-defined problems do not. Well-defined problems allow for more initial planning than ill-defined problems. Solving problems sometimes involves dealing with pragmatics (the way that context contributes to meaning) and semantics (the interpretation of the problem). The ability to understand what the end goal of the problem is, and what rules could be applied, represents the key to solving the problem. Sometimes a problem requires abstract thinking or coming up with a creative solution. Problem solving has two major domains: mathematical problem solving and personal problem solving. Each concerns some difficulty or barrier that is encountered.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Problem solving: Psychology', 'Problem solving in psychology refers to the process of finding solutions to problems encountered in life. Solutions to these problems are usually situation- or context-specific. The process starts with problem finding, in which the problem is discovered and simplified. The next step is to generate possible solutions and evaluate them. Finally a solution is selected to be implemented and verified. Problems have an end goal to be reached; how you get there depends upon problem orientation (problem-solving coping style and skills) and systematic analysis. Mental health professionals study the human problem-solving processes using methods such as introspection, behaviorism, simulation, computer modeling, and experiment. Social psychologists look into the person-environment relationship aspect of the problem and independent and interdependent problem-solving methods. Problem solving has been defined as a higher-order cognitive process and intellectual function that requires the modulation and control of more routine or fundamental skills.', 'Wikipedia: Problem solving', 'https://en.wikipedia.org/w/index.php?title=Problem_solving&oldid=1378905256', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Problem solving in psychology refers to the process of finding solutions to problems encountered in life. Solutions to these problems are usually situation- or context-specific. The process starts with problem finding, in which the problem is discovered and simplified. The next step is to generate possible solutions and evaluate them. Finally a solution is selected to be implemented and verified. Problems have an end goal to be reached; how you get there depends upon problem orientation (problem-solving coping style and skills) and systematic analysis. Mental health professionals study the human problem-solving processes using methods such as introspection, behaviorism, simulation, computer modeling, and experiment. Social psychologists look into the person-environment relationship aspect of the problem and independent and interdependent problem-solving methods. Problem solving has been defined as a higher-order cognitive process and intellectual function that requires the modulation and control of more routine or fundamental skills.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Problem solving: Psychology', 'Empirical research shows many different strategies and factors influence everyday problem solving. Rehabilitation psychologists studying people with frontal lobe injuries have found that deficits in emotional control and reasoning can be re-mediated with effective rehabilitation and could improve the capacity of injured persons to resolve everyday problems. Interpersonal everyday problem solving is dependent upon personal motivational and contextual components. One such component is the emotional valence of "real-world" problems, which can either impede or aid problem-solving performance. Researchers have focused on the role of emotions in problem solving, demonstrating that poor emotional control can disrupt focus on the target task, impede problem resolution, and lead to negative outcomes such as fatigue, depression, and inertia. In conceptualization,human problem solving consists of two related processes: problem orientation, and the motivational/attitudinal/affective approach to problematic situations and problem-solving skills. People''s strategies cohere with their goals and stem from the process of comparing oneself with others.', 'Wikipedia: Problem solving', 'https://en.wikipedia.org/w/index.php?title=Problem_solving&oldid=1378905256', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Empirical research shows many different strategies and factors influence everyday problem solving. Rehabilitation psychologists studying people with frontal lobe injuries have found that deficits in emotional control and reasoning can be re-mediated with effective rehabilitation and could improve the capacity of injured persons to resolve everyday problems. Interpersonal everyday problem solving is dependent upon personal motivational and contextual components. One such component is the emotional valence of "real-world" problems, which can either impede or aid problem-solving performance. Researchers have focused on the role of emotions in problem solving, demonstrating that poor emotional control can disrupt focus on the target task, impede problem resolution, and lead to negative outcomes such as fatigue, depression, and inertia. In conceptualization,human problem solving consists of two related processes: problem orientation, and the motivational/attitudinal/affective approach to problematic situations and problem-solving skills. People''s strategies cohere with their goals and stem from the process of comparing oneself with others.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Problem solving: Cognitive sciences', 'Among the first experimental psychologists to study problem solving were the Gestaltists in Germany, such as Karl Duncker in The Psychology of Productive Thinking (1935). Perhaps best known is the work of Allen Newell and Herbert A. Simon. Experiments in the 1960s and early 1970s asked participants to solve relatively simple, well-defined, but not previously seen laboratory tasks. These simple problems, such as the Tower of Hanoi, admitted optimal solutions that could be found quickly, allowing researchers to observe the full problem-solving process. Researchers assumed that these model problems would elicit the characteristic cognitive processes by which more complex "real world" problems are solved. An outstanding problem-solving technique found by this research is the principle of decomposition.', 'Wikipedia: Problem solving', 'https://en.wikipedia.org/w/index.php?title=Problem_solving&oldid=1378905256', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Among the first experimental psychologists to study problem solving were the Gestaltists in Germany, such as Karl Duncker in The Psychology of Productive Thinking (1935). Perhaps best known is the work of Allen Newell and Herbert A. Simon. Experiments in the 1960s and early 1970s asked participants to solve relatively simple, well-defined, but not previously seen laboratory tasks. These simple problems, such as the Tower of Hanoi, admitted optimal solutions that could be found quickly, allowing researchers to observe the full problem-solving process. Researchers assumed that these model problems would elicit the characteristic cognitive processes by which more complex "real world" problems are solved. An outstanding problem-solving technique found by this research is the principle of decomposition.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Problem solving: Computer science', 'Much of computer science and artificial intelligence involves designing automated systems to solve a specified type of problem: to accept input data and calculate a correct or adequate response, reasonably quickly. Algorithms are recipes or instructions that direct such systems, written into computer programs. Steps for designing such systems include problem determination, heuristics, root cause analysis, de-duplication, analysis, diagnosis, and repair. Analytic techniques include linear and nonlinear programming, queuing systems, and simulation. A large, perennial obstacle is to find and fix errors in computer programs: debugging.', 'Wikipedia: Problem solving', 'https://en.wikipedia.org/w/index.php?title=Problem_solving&oldid=1378905256', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Much of computer science and artificial intelligence involves designing automated systems to solve a specified type of problem: to accept input data and calculate a correct or adequate response, reasonably quickly. Algorithms are recipes or instructions that direct such systems, written into computer programs. Steps for designing such systems include problem determination, heuristics, root cause analysis, de-duplication, analysis, diagnosis, and repair. Analytic techniques include linear and nonlinear programming, queuing systems, and simulation. A large, perennial obstacle is to find and fix errors in computer programs: debugging.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Problem solving: Logic', 'Formal logic concerns issues like validity, truth, inference, argumentation, and proof. In a problem-solving context, it can be used to formally represent a problem as a theorem to be proved, and to represent the knowledge needed to solve the problem as the premises to be used in a proof that the problem has a solution. The use of computers to prove mathematical theorems using formal logic emerged as the field of automated theorem proving in the 1950s. It included the use of heuristic methods designed to simulate human problem solving, as in the Logic Theory Machine, developed by Allen Newell, Herbert A. Simon and J. C. Shaw, as well as algorithmic methods such as the resolution principle developed by John Alan Robinson. In addition to its use for finding proofs of mathematical theorems, automated theorem-proving has also been used for program verification in computer science. In 1958, John McCarthy proposed the advice taker, to represent information in formal logic and to derive answers to questions using automated theorem-proving. An important step in this direction was made by Cordell Green in 1969, who used a resolution theorem prover for question-answering and for such other applications in artificial intelligence as robot planning.', 'Wikipedia: Problem solving', 'https://en.wikipedia.org/w/index.php?title=Problem_solving&oldid=1378905256', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Formal logic concerns issues like validity, truth, inference, argumentation, and proof. In a problem-solving context, it can be used to formally represent a problem as a theorem to be proved, and to represent the knowledge needed to solve the problem as the premises to be used in a proof that the problem has a solution. The use of computers to prove mathematical theorems using formal logic emerged as the field of automated theorem proving in the 1950s. It included the use of heuristic methods designed to simulate human problem solving, as in the Logic Theory Machine, developed by Allen Newell, Herbert A. Simon and J. C. Shaw, as well as algorithmic methods such as the resolution principle developed by John Alan Robinson. In addition to its use for finding proofs of mathematical theorems, automated theorem-proving has also been used for program verification in computer science. In 1958, John McCarthy proposed the advice taker, to represent information in formal logic and to derive answers to questions using automated theorem-proving. An important step in this direction was made by Cordell Green in 1969, who used a resolution theorem prover for question-answering and for such other applications in artificial intelligence as robot planning.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Heuristic (psychology)', 'Heuristics (from Ancient Greek εὑρίσκω (heurískō) ''to find, discover'') is the process by which humans use mental shortcuts to arrive at decisions. Heuristics are simple strategies that humans, animals, organizations, and even machines use to quickly form judgments, make decisions, and find solutions to complex problems. Often this involves focusing on the most relevant aspects of a problem or situation to formulate a solution. While heuristic processes are used to find the answers and solutions that are most likely to work or be correct, they are not always right or the most accurate. Judgments and decisions based on heuristics are simply good enough to satisfy a pressing need in situations of uncertainty, where information is incomplete. In that sense they can differ from answers given by logic and probability.', 'Wikipedia: Heuristic (psychology)', 'https://en.wikipedia.org/w/index.php?title=Heuristic_(psychology)&oldid=1380684160', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Heuristics (from Ancient Greek εὑρίσκω (heurískō) ''to find, discover'') is the process by which humans use mental shortcuts to arrive at decisions. Heuristics are simple strategies that humans, animals, organizations, and even machines use to quickly form judgments, make decisions, and find solutions to complex problems. Often this involves focusing on the most relevant aspects of a problem or situation to formulate a solution. While heuristic processes are used to find the answers and solutions that are most likely to work or be correct, they are not always right or the most accurate. Judgments and decisions based on heuristics are simply good enough to satisfy a pressing need in situations of uncertainty, where information is incomplete. In that sense they can differ from answers given by logic and probability.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Heuristic (psychology)', 'The economist and cognitive psychologist Herbert A. Simon introduced the concept of heuristics in the 1950s, suggesting there were limitations to rational decision making. In the 1970s, psychologists Amos Tversky and Daniel Kahneman added to the field with their research on cognitive bias. It was their work that introduced specific heuristic models, a field which has only expanded since. While some argue that pure laziness is behind the heuristics process, this could just be a simplified explanation for why people don''t act the way we expected them to. Other theories argue that it can be more accurate than decisions based on every known factor and consequence, such as the less-is-more effect.', 'Wikipedia: Heuristic (psychology)', 'https://en.wikipedia.org/w/index.php?title=Heuristic_(psychology)&oldid=1380684160', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'The economist and cognitive psychologist Herbert A. Simon introduced the concept of heuristics in the 1950s, suggesting there were limitations to rational decision making. In the 1970s, psychologists Amos Tversky and Daniel Kahneman added to the field with their research on cognitive bias. It was their work that introduced specific heuristic models, a field which has only expanded since. While some argue that pure laziness is behind the heuristics process, this could just be a simplified explanation for why people don''t act the way we expected them to. Other theories argue that it can be more accurate than decisions based on every known factor and consequence, such as the less-is-more effect.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Heuristic (psychology): Simon''s satisficing strategy', 'Herbert Simon''s satisficing heuristic can be used to choose one alternative from a set of alternatives in situations of uncertainty. Here, uncertainty means that the total set of alternatives and their consequences is not known or knowable. For instance, professional real-estate entrepreneurs rely on satisficing to decide in which location to invest to develop new commercial areas: "If I believe I can get at least x return within y years, then I take the option." In general, satisficing is defined as: If no alternative is found, then the aspiration level can be adapted. Step 3: If after time β no alternative has satisfied α, then decrease α by some amount δ and return to step 1. Satisficing has been reported across many domains, for instance as a heuristic car dealers use to price used BMWs.', 'Wikipedia: Heuristic (psychology)', 'https://en.wikipedia.org/w/index.php?title=Heuristic_(psychology)&oldid=1380684160', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Herbert Simon''s satisficing heuristic can be used to choose one alternative from a set of alternatives in situations of uncertainty. Here, uncertainty means that the total set of alternatives and their consequences is not known or knowable. For instance, professional real-estate entrepreneurs rely on satisficing to decide in which location to invest to develop new commercial areas: "If I believe I can get at least x return within y years, then I take the option." In general, satisficing is defined as: If no alternative is found, then the aspiration level can be adapted. Step 3: If after time β no alternative has satisfied α, then decrease α by some amount δ and return to step 1. Satisficing has been reported across many domains, for instance as a heuristic car dealers use to price used BMWs.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Heuristic (psychology): Elimination by aspects', 'Unlike satisficing, Amos Tversky''s elimination-by-aspect heuristic can be used when all alternatives are simultaneously available. The decision-maker gradually reduces the number of alternatives by eliminating alternatives that do not meet the aspiration level of a specific attribute (or aspect). During a series of selections, people tend to experience uncertainty and exhibit inconsistency. Elimination by aspects could be used when facing selections. In general, the process of elimination by aspects is as follows: Step 4: Repeat step 3 until only one option is left, a decision has then been made Elimination by aspects does not speculate that choosing alternatives could help consumers to maximize utility, on the contrary, it holds that selection is the result of a probabilistic process that gradually eliminates alternatives. A simple example is given by Amos Tversky: when someone wants to purchase a new car, the first aspect they will take into account might be the automatic transmission, this will eliminate all alternatives that do not contain such an aspect. Then, when all the alternatives that do not have this feature are eliminated, another aspect will be given such as a $3000 price limit. The process of elimination continues to occur until all alternatives are eliminated.', 'Wikipedia: Heuristic (psychology)', 'https://en.wikipedia.org/w/index.php?title=Heuristic_(psychology)&oldid=1380684160', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Unlike satisficing, Amos Tversky''s elimination-by-aspect heuristic can be used when all alternatives are simultaneously available. The decision-maker gradually reduces the number of alternatives by eliminating alternatives that do not meet the aspiration level of a specific attribute (or aspect). During a series of selections, people tend to experience uncertainty and exhibit inconsistency. Elimination by aspects could be used when facing selections. In general, the process of elimination by aspects is as follows: Step 4: Repeat step 3 until only one option is left, a decision has then been made Elimination by aspects does not speculate that choosing alternatives could help consumers to maximize utility, on the contrary, it holds that selection is the result of a probabilistic process that gradually eliminates alternatives. A simple example is given by Amos Tversky: when someone wants to purchase a new car, the first aspect they will take into account might be the automatic transmission, this will eliminate all alternatives that do not contain such an aspect. Then, when all the alternatives that do not have this feature are eliminated, another aspect will be given such as a $3000 price limit. The process of elimination continues to occur until all alternatives are eliminated.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Heuristic (psychology): Elimination by aspects', 'Elimination by aspects is well used in the early stage of business angels'' decision-making process since it facilitates a fast-decision-making tool - alternatives will be eliminated when investors find a critical defect of the potential opportunities. Another research also demonstrated that elimination by aspects has widely been used in electricity contract choice. The logic behind these two examples is that elimination by aspects helps to make decisions when facing a series of complicated choices. One may need to make a decision among all alternatives while he or she only has limited intuitive computational facilities and time. However, elimination by aspects as a compensatory model could help to make such complex decisions since it is easier to apply and involves nonnumerical computations.', 'Wikipedia: Heuristic (psychology)', 'https://en.wikipedia.org/w/index.php?title=Heuristic_(psychology)&oldid=1380684160', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Elimination by aspects is well used in the early stage of business angels'' decision-making process since it facilitates a fast-decision-making tool - alternatives will be eliminated when investors find a critical defect of the potential opportunities. Another research also demonstrated that elimination by aspects has widely been used in electricity contract choice. The logic behind these two examples is that elimination by aspects helps to make decisions when facing a series of complicated choices. One may need to make a decision among all alternatives while he or she only has limited intuitive computational facilities and time. However, elimination by aspects as a compensatory model could help to make such complex decisions since it is easier to apply and involves nonnumerical computations.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Heuristic (psychology): Recognition heuristic', 'The recognition heuristic exploits the basic psychological capacity for recognition in order to make inferences about unknown quantities in the world. For two alternatives, the heuristic is:If one of two alternatives is recognized and the other not, then infer that the recognized alternative has the higher value with respect to the criterion. For example, in the 2003 Wimbledon tennis tournament, Andy Roddick played Tommy Robredo. If one has heard of Roddick but not of Robredo, the recognition heuristic leads to the prediction that Roddick will win. The recognition heuristic exploits partial ignorance, if one has heard of both or no player, a different strategy is needed. Studies of Wimbledon 2003 and 2005 have shown that the recognition heuristic applied by semi-ignorant amateur players predicted the outcomes of all gentlemen single games as well and better than the seedings of the Wimbledon experts (who had heard of all players), as well as the ATP rankings. The recognition heuristic is ecologically rational (that is, it predicts well) when the recognition validity is substantially above chance. In the present case, recognition of players'' names is highly correlated with their chances of winning.', 'Wikipedia: Heuristic (psychology)', 'https://en.wikipedia.org/w/index.php?title=Heuristic_(psychology)&oldid=1380684160', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'The recognition heuristic exploits the basic psychological capacity for recognition in order to make inferences about unknown quantities in the world. For two alternatives, the heuristic is:If one of two alternatives is recognized and the other not, then infer that the recognized alternative has the higher value with respect to the criterion. For example, in the 2003 Wimbledon tennis tournament, Andy Roddick played Tommy Robredo. If one has heard of Roddick but not of Robredo, the recognition heuristic leads to the prediction that Roddick will win. The recognition heuristic exploits partial ignorance, if one has heard of both or no player, a different strategy is needed. Studies of Wimbledon 2003 and 2005 have shown that the recognition heuristic applied by semi-ignorant amateur players predicted the outcomes of all gentlemen single games as well and better than the seedings of the Wimbledon experts (who had heard of all players), as well as the ATP rankings. The recognition heuristic is ecologically rational (that is, it predicts well) when the recognition validity is substantially above chance. In the present case, recognition of players'' names is highly correlated with their chances of winning.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Heuristic (psychology): Take-the-best', 'The take-the-best heuristic exploits the basic psychological capacity for retrieving cues from memory in the order of their validity. Based on the cue values, it infers which of two alternatives has a higher value on a criterion. Unlike the recognition heuristic, it requires that all alternatives are recognized, and it thus can be applied when the recognition heuristic cannot. For binary cues (where 1 indicates the higher criterion value), the heuristic is defined as: The validity vi of a cue i is defined as the proportion of correct decisions ci: where ti is the number of cases the values of the two alternatives differ on cue i. The validity of each cue can be estimated from samples of observation. Take-the-best has remarkable properties. In comparison with complex machine learning models, it has been shown that it can often predict better than regression models, classification-and-regression trees, neural networks, and support vector machines. [Brighton & Gigerenzer, 2015]', 'Wikipedia: Heuristic (psychology)', 'https://en.wikipedia.org/w/index.php?title=Heuristic_(psychology)&oldid=1380684160', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'The take-the-best heuristic exploits the basic psychological capacity for retrieving cues from memory in the order of their validity. Based on the cue values, it infers which of two alternatives has a higher value on a criterion. Unlike the recognition heuristic, it requires that all alternatives are recognized, and it thus can be applied when the recognition heuristic cannot. For binary cues (where 1 indicates the higher criterion value), the heuristic is defined as: The validity vi of a cue i is defined as the proportion of correct decisions ci: where ti is the number of cases the values of the two alternatives differ on cue i. The validity of each cue can be estimated from samples of observation. Take-the-best has remarkable properties. In comparison with complex machine learning models, it has been shown that it can often predict better than regression models, classification-and-regression trees, neural networks, and support vector machines. [Brighton & Gigerenzer, 2015]');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Heuristic (psychology): Take-the-best', 'Similarly, psychological studies have shown that in situations where take-the-best is ecologically rational, a large proportion of people tend to rely on it. This includes decision making by airport custom officers, professional burglars and police officers and student populations. The conditions under which take-the-best is ecologically rational are mostly known. Take-the-best shows that the previous view that ignoring part of the information would be generally irrational is incorrect. Less can be more.', 'Wikipedia: Heuristic (psychology)', 'https://en.wikipedia.org/w/index.php?title=Heuristic_(psychology)&oldid=1380684160', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Similarly, psychological studies have shown that in situations where take-the-best is ecologically rational, a large proportion of people tend to rely on it. This includes decision making by airport custom officers, professional burglars and police officers and student populations. The conditions under which take-the-best is ecologically rational are mostly known. Take-the-best shows that the previous view that ignoring part of the information would be generally irrational is incorrect. Less can be more.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Cognitive bias', 'A cognitive bias is a systematic pattern of deviation from the norm or rationality in judgment. Individuals create their own "subjective reality" from their perception of the input. An individual''s construction of reality, not the objective input, may dictate their behavior in the world. Thus, cognitive biases may sometimes lead to perceptual distortion, inaccurate judgment, illogical interpretation, and irrationality. While cognitive biases may initially appear to be negative, some are adaptive. They may lead to more effective actions in a given context. Furthermore, allowing cognitive biases enables faster decisions which can be desirable when timeliness is more valuable than accuracy, as illustrated in heuristics. Other cognitive biases are a "by-product" of human processing limitations, resulting from a lack of appropriate mental mechanisms (bounded rationality), the impact of an individual''s constitution and biological state (embodied cognition), or simply from a limited capacity for information processing. Cognitive biases can make individuals more inclined to endorsing pseudoscientific beliefs by requiring less evidence for claims that confirm their preconceptions. This can potentially distort their perceptions and lead to inaccurate judgments.', 'Wikipedia: Cognitive bias', 'https://en.wikipedia.org/w/index.php?title=Cognitive_bias&oldid=1379095929', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'A cognitive bias is a systematic pattern of deviation from the norm or rationality in judgment. Individuals create their own "subjective reality" from their perception of the input. An individual''s construction of reality, not the objective input, may dictate their behavior in the world. Thus, cognitive biases may sometimes lead to perceptual distortion, inaccurate judgment, illogical interpretation, and irrationality. While cognitive biases may initially appear to be negative, some are adaptive. They may lead to more effective actions in a given context. Furthermore, allowing cognitive biases enables faster decisions which can be desirable when timeliness is more valuable than accuracy, as illustrated in heuristics. Other cognitive biases are a "by-product" of human processing limitations, resulting from a lack of appropriate mental mechanisms (bounded rationality), the impact of an individual''s constitution and biological state (embodied cognition), or simply from a limited capacity for information processing. Cognitive biases can make individuals more inclined to endorsing pseudoscientific beliefs by requiring less evidence for claims that confirm their preconceptions. This can potentially distort their perceptions and lead to inaccurate judgments.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Cognitive bias', 'A continually evolving list of cognitive biases has been identified over the last six decades of research on human judgment and decision-making in cognitive science, social psychology, and behavioral economics. The study of cognitive biases has practical implications for areas including clinical judgment, entrepreneurship, finance, and management.', 'Wikipedia: Cognitive bias', 'https://en.wikipedia.org/w/index.php?title=Cognitive_bias&oldid=1379095929', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
