insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Cognitive bias: Overview', 'When making judgments under uncertainty, people rely on mental shortcuts or heuristics, which provide swift estimates about the possibility of uncertain occurrences. For example, the representativeness heuristic is defined as the tendency to judge the frequency or likelihood of an occurrence by the extent of which the event resembles the typical case. Similarly the availability heuristic is that individuals estimate the likelihood of events by how easy they are to recall, and the anchoring heuristic prefers the initial reference points that are recalled. While these heuristics are efficient and simple for the brain to compute, they sometimes introduce predictable and systematic cognitive errors, or biases.', 'Wikipedia: Cognitive bias', 'https://en.wikipedia.org/w/index.php?title=Cognitive_bias&oldid=1379095929', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'When making judgments under uncertainty, people rely on mental shortcuts or heuristics, which provide swift estimates about the possibility of uncertain occurrences. For example, the representativeness heuristic is defined as the tendency to judge the frequency or likelihood of an occurrence by the extent of which the event resembles the typical case. Similarly the availability heuristic is that individuals estimate the likelihood of events by how easy they are to recall, and the anchoring heuristic prefers the initial reference points that are recalled. While these heuristics are efficient and simple for the brain to compute, they sometimes introduce predictable and systematic cognitive errors, or biases.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Cognitive bias: Overview', 'The "Linda Problem" illustrates the representativeness heuristic and corresponding bias. Participants were given a description of "Linda" that suggests Linda might well be a feminist (e.g., she is said to be concerned about discrimination and social justice issues). They were then asked whether they thought Linda was more likely to be (a) a "bank teller" or (b) a "bank teller and active in the feminist movement". A majority chose answer (b). Independent of the information given about Linda, though, the more restrictive answer (b) is under any circumstance statistically less likely than answer (a). This is an example of the conjunction fallacy: respondents chose (b) because it seemed more "representative" or typical of persons who might fit the description of Linda. If they assumed that choosing (a) would entail Linda not being active in the feminist movement, that would be a pragmatic implicature. The representativeness heuristic may lead to errors such as activating stereotypes and inaccurate judgments of others.', 'Wikipedia: Cognitive bias', 'https://en.wikipedia.org/w/index.php?title=Cognitive_bias&oldid=1379095929', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'The "Linda Problem" illustrates the representativeness heuristic and corresponding bias. Participants were given a description of "Linda" that suggests Linda might well be a feminist (e.g., she is said to be concerned about discrimination and social justice issues). They were then asked whether they thought Linda was more likely to be (a) a "bank teller" or (b) a "bank teller and active in the feminist movement". A majority chose answer (b). Independent of the information given about Linda, though, the more restrictive answer (b) is under any circumstance statistically less likely than answer (a). This is an example of the conjunction fallacy: respondents chose (b) because it seemed more "representative" or typical of persons who might fit the description of Linda. If they assumed that choosing (a) would entail Linda not being active in the feminist movement, that would be a pragmatic implicature. The representativeness heuristic may lead to errors such as activating stereotypes and inaccurate judgments of others.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Cognitive bias: Overview', 'Gerd Gigerenzer argues that heuristics should not lead us to conceive of human thinking as riddled with irrational cognitive biases. They should rather conceive rationality as an adaptive tool, not identical to the rules of formal logic or the probability calculus. Gigerenzer believes that cognitive biases are not biases, but rules of thumb, or as he would put it "gut feelings" that can actually help us make accurate decisions in our lives. There is not clear evidence that these behaviors are genuinely, severely biased once the actual problems people face are understood. Advances in economics and cognitive neuroscience now suggest that many behaviors previously labeled as biases might instead represent optimal decision-making strategies.', 'Wikipedia: Cognitive bias', 'https://en.wikipedia.org/w/index.php?title=Cognitive_bias&oldid=1379095929', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Gerd Gigerenzer argues that heuristics should not lead us to conceive of human thinking as riddled with irrational cognitive biases. They should rather conceive rationality as an adaptive tool, not identical to the rules of formal logic or the probability calculus. Gigerenzer believes that cognitive biases are not biases, but rules of thumb, or as he would put it "gut feelings" that can actually help us make accurate decisions in our lives. There is not clear evidence that these behaviors are genuinely, severely biased once the actual problems people face are understood. Advances in economics and cognitive neuroscience now suggest that many behaviors previously labeled as biases might instead represent optimal decision-making strategies.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Cognitive bias: Types', 'Biases specific to groups (such as the risky shift) versus biases at the individual level. Biases that affect decision-making, where the desirability of options has to be considered (e.g., sunk costs fallacy). Biases, such as illusory correlation, that affect judgment of how likely something is or whether one thing is the cause of another. Biases that affect memory, such as consistency bias (remembering one''s past attitudes and behavior as more similar to one''s present attitudes). Biases that reflect a subject''s motivation, for example, the desire for a positive self-image leading to egocentric bias and the avoidance of unpleasant cognitive dissonance. Other biases are due to the particular way the brain perceives, forms memories and makes judgments. This distinction is sometimes described as "hot cognition" versus "cold cognition", as motivated reasoning can involve a state of arousal. Among the "cold" biases, some involve a decision or judgment being affected by irrelevant information (for example the framing effect where the same problem receives different responses depending on how it is described; or the distinction bias where choices presented together have different outcomes than those presented separately), and others give excessive weight to an unimportant but salient feature of the problem (e.g., anchoring).', 'Wikipedia: Cognitive bias', 'https://en.wikipedia.org/w/index.php?title=Cognitive_bias&oldid=1379095929', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Biases specific to groups (such as the risky shift) versus biases at the individual level. Biases that affect decision-making, where the desirability of options has to be considered (e.g., sunk costs fallacy). Biases, such as illusory correlation, that affect judgment of how likely something is or whether one thing is the cause of another. Biases that affect memory, such as consistency bias (remembering one''s past attitudes and behavior as more similar to one''s present attitudes). Biases that reflect a subject''s motivation, for example, the desire for a positive self-image leading to egocentric bias and the avoidance of unpleasant cognitive dissonance. Other biases are due to the particular way the brain perceives, forms memories and makes judgments. This distinction is sometimes described as "hot cognition" versus "cold cognition", as motivated reasoning can involve a state of arousal. Among the "cold" biases, some involve a decision or judgment being affected by irrelevant information (for example the framing effect where the same problem receives different responses depending on how it is described; or the distinction bias where choices presented together have different outcomes than those presented separately), and others give excessive weight to an unimportant but salient feature of the problem (e.g., anchoring).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Cognitive bias: Types', 'As some biases reflect motivation specifically the motivation to have positive attitudes to oneself. It accounts for the fact that many biases are self-motivated or self-directed (e.g., illusion of asymmetric insight, self-serving bias). There are also biases in how subjects evaluate in-groups or out-groups; evaluating in-groups as more diverse and "better" in many respects, even when those groups are arbitrarily defined (ingroup bias, outgroup homogeneity bias). Some cognitive biases belong to the subgroup of attentional biases, which refers to paying increased attention to certain stimuli. It has been shown, for example, that people addicted to alcohol and other drugs pay more attention to drug-related stimuli. Common psychological tests to measure those biases are the Stroop task and the dot probe task. Individuals'' susceptibility to some types of cognitive biases can be measured by the Cognitive Reflection Test (CRT) developed by Shane Frederick (2005).', 'Wikipedia: Cognitive bias', 'https://en.wikipedia.org/w/index.php?title=Cognitive_bias&oldid=1379095929', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'As some biases reflect motivation specifically the motivation to have positive attitudes to oneself. It accounts for the fact that many biases are self-motivated or self-directed (e.g., illusion of asymmetric insight, self-serving bias). There are also biases in how subjects evaluate in-groups or out-groups; evaluating in-groups as more diverse and "better" in many respects, even when those groups are arbitrarily defined (ingroup bias, outgroup homogeneity bias). Some cognitive biases belong to the subgroup of attentional biases, which refers to paying increased attention to certain stimuli. It has been shown, for example, that people addicted to alcohol and other drugs pay more attention to drug-related stimuli. Common psychological tests to measure those biases are the Stroop task and the dot probe task. Individuals'' susceptibility to some types of cognitive biases can be measured by the Cognitive Reflection Test (CRT) developed by Shane Frederick (2005).');
