insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Confirmation bias', 'Confirmation bias (also confirmatory bias, myside bias, or congeniality bias) is the tendency to search for, interpret, favor and recall information in a way that confirms or supports one''s prior beliefs, values, or decisions. People display this bias when they select information that supports their views, ignoring contrary information or when they interpret ambiguous evidence as supporting their existing attitudes. The effect is strongest for desired outcomes, emotionally charged issues and deeply entrenched beliefs. Confirmation bias often comes from automatic mental habits. Studies repeatedly find that people tend to test ideas in a one sided way, mainly searching for evidence that supports what they already assume. Research on selective exposure also suggests that people differ in how strongly they defend their attitudes, with some individuals being more resistant to information that goes against their views. Biased search for information, biased interpretation of this information and biased memory recall have been invoked to explain four specific effects: attitude polarization (when a disagreement becomes more extreme despite the different parties being exposed to the same evidence) belief perseverance (when beliefs persist after the evidence for them is shown to be false) the irrational primacy effect (a greater reliance on information encountered early in a series) illusory correlation (when people falsely perceive an association between two events or situations).', 'Wikipedia: Confirmation bias', 'https://en.wikipedia.org/w/index.php?title=Confirmation_bias&oldid=1370294982', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Confirmation bias (also confirmatory bias, myside bias, or congeniality bias) is the tendency to search for, interpret, favor and recall information in a way that confirms or supports one''s prior beliefs, values, or decisions. People display this bias when they select information that supports their views, ignoring contrary information or when they interpret ambiguous evidence as supporting their existing attitudes. The effect is strongest for desired outcomes, emotionally charged issues and deeply entrenched beliefs. Confirmation bias often comes from automatic mental habits. Studies repeatedly find that people tend to test ideas in a one sided way, mainly searching for evidence that supports what they already assume. Research on selective exposure also suggests that people differ in how strongly they defend their attitudes, with some individuals being more resistant to information that goes against their views. Biased search for information, biased interpretation of this information and biased memory recall have been invoked to explain four specific effects: attitude polarization (when a disagreement becomes more extreme despite the different parties being exposed to the same evidence) belief perseverance (when beliefs persist after the evidence for them is shown to be false) the irrational primacy effect (a greater reliance on information encountered early in a series) illusory correlation (when people falsely perceive an association between two events or situations).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Confirmation bias', 'A series of psychological experiments in the 1960s suggested that people are biased toward confirming their existing beliefs. Later work reinterpreted these results as a tendency to test ideas in a one-sided way, focusing on one possibility and ignoring alternatives. Explanations for the observed biases include wishful thinking and the limited human capacity to process information. Another proposal is that people show confirmation bias because they are pragmatically assessing the costs of being wrong rather than investigating in a neutral, scientific way. Flawed decisions due to confirmation bias have been found in a wide range of political, organizational, financial and scientific contexts. These biases contribute to overconfidence in personal beliefs and can maintain or strengthen beliefs in the face of contrary evidence. For example, confirmation bias produces systematic errors in scientific research based on inductive reasoning (the gradual accumulation of supportive evidence). Similarly, a police detective may identify a suspect early in an investigation, but then may only seek confirming rather than disconfirming evidence. A medical practitioner may prematurely focus on a particular disorder early in a diagnostic session, and then seek only confirming evidence. In social media, confirmation bias is amplified by the use of filter bubbles and "algorithmic editing", which display to individuals only information they are likely to agree with, while excluding opposing views.', 'Wikipedia: Confirmation bias', 'https://en.wikipedia.org/w/index.php?title=Confirmation_bias&oldid=1370294982', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'A series of psychological experiments in the 1960s suggested that people are biased toward confirming their existing beliefs. Later work reinterpreted these results as a tendency to test ideas in a one-sided way, focusing on one possibility and ignoring alternatives. Explanations for the observed biases include wishful thinking and the limited human capacity to process information. Another proposal is that people show confirmation bias because they are pragmatically assessing the costs of being wrong rather than investigating in a neutral, scientific way. Flawed decisions due to confirmation bias have been found in a wide range of political, organizational, financial and scientific contexts. These biases contribute to overconfidence in personal beliefs and can maintain or strengthen beliefs in the face of contrary evidence. For example, confirmation bias produces systematic errors in scientific research based on inductive reasoning (the gradual accumulation of supportive evidence). Similarly, a police detective may identify a suspect early in an investigation, but then may only seek confirming rather than disconfirming evidence. A medical practitioner may prematurely focus on a particular disorder early in a diagnostic session, and then seek only confirming evidence. In social media, confirmation bias is amplified by the use of filter bubbles and "algorithmic editing", which display to individuals only information they are likely to agree with, while excluding opposing views.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Confirmation bias: Definition and context', 'Confirmation bias, previously used as a "catch-all phrase", was refined by English psychologist Peter Wason, as "a preference for information that is consistent with a hypothesis rather than information which opposes it." Confirmation biases are effects in information processing. They differ from what is sometimes called the behavioral confirmation effect, commonly known as self-fulfilling prophecy, in which a person''s expectations influence their own behavior, bringing about the expected result. Some psychologists restrict the term "confirmation bias" to selective collection of evidence that supports what one already believes while ignoring or rejecting evidence that supports a different conclusion. Others apply the term more broadly to the tendency to preserve one''s existing beliefs when searching for evidence, interpreting it, or recalling it from memory. Confirmation bias is a result of automatic, unintentional strategies rather than deliberate deception.', 'Wikipedia: Confirmation bias', 'https://en.wikipedia.org/w/index.php?title=Confirmation_bias&oldid=1370294982', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Confirmation bias, previously used as a "catch-all phrase", was refined by English psychologist Peter Wason, as "a preference for information that is consistent with a hypothesis rather than information which opposes it." Confirmation biases are effects in information processing. They differ from what is sometimes called the behavioral confirmation effect, commonly known as self-fulfilling prophecy, in which a person''s expectations influence their own behavior, bringing about the expected result. Some psychologists restrict the term "confirmation bias" to selective collection of evidence that supports what one already believes while ignoring or rejecting evidence that supports a different conclusion. Others apply the term more broadly to the tendency to preserve one''s existing beliefs when searching for evidence, interpreting it, or recalling it from memory. Confirmation bias is a result of automatic, unintentional strategies rather than deliberate deception.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Confirmation bias: Biased search for information', 'Experiments have found repeatedly that people tend to test hypotheses in a one-sided way, by searching for evidence consistent with their current hypothesis. Rather than searching through all the relevant evidence, they phrase questions to receive an affirmative answer that supports their theory. They look for the consequences that they would expect if their hypothesis were true, rather than what would happen if it were false. For example, someone using yes/no questions to find a number they suspect to be the number 3 might ask, "Is it an odd number?" People prefer this type of question, called a "positive test", even when a negative test such as "Is it an even number?" would yield exactly the same information. However, this does not mean that people seek tests that guarantee a positive answer. In studies where subjects could select either such pseudo-tests or genuinely diagnostic ones, they favored the genuinely diagnostic.', 'Wikipedia: Confirmation bias', 'https://en.wikipedia.org/w/index.php?title=Confirmation_bias&oldid=1370294982', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Experiments have found repeatedly that people tend to test hypotheses in a one-sided way, by searching for evidence consistent with their current hypothesis. Rather than searching through all the relevant evidence, they phrase questions to receive an affirmative answer that supports their theory. They look for the consequences that they would expect if their hypothesis were true, rather than what would happen if it were false. For example, someone using yes/no questions to find a number they suspect to be the number 3 might ask, "Is it an odd number?" People prefer this type of question, called a "positive test", even when a negative test such as "Is it an even number?" would yield exactly the same information. However, this does not mean that people seek tests that guarantee a positive answer. In studies where subjects could select either such pseudo-tests or genuinely diagnostic ones, they favored the genuinely diagnostic.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Confirmation bias: Biased search for information', 'The preference for positive tests in itself is not a bias, since positive tests can be highly informative. However, in combination with other effects, this strategy can confirm existing beliefs or assumptions, independently of whether they are true. In real-world situations, evidence is often complex and mixed. For example, various contradictory ideas about someone could each be supported by concentrating on one aspect of his or her behavior. Thus any search for evidence in favor of a hypothesis is likely to succeed. One illustration of this is the way the phrasing of a question can significantly change the answer. For example, people who are asked, "Are you happy with your social life?" report greater satisfaction than those asked, "Are you unhappy with your social life?"', 'Wikipedia: Confirmation bias', 'https://en.wikipedia.org/w/index.php?title=Confirmation_bias&oldid=1370294982', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'The preference for positive tests in itself is not a bias, since positive tests can be highly informative. However, in combination with other effects, this strategy can confirm existing beliefs or assumptions, independently of whether they are true. In real-world situations, evidence is often complex and mixed. For example, various contradictory ideas about someone could each be supported by concentrating on one aspect of his or her behavior. Thus any search for evidence in favor of a hypothesis is likely to succeed. One illustration of this is the way the phrasing of a question can significantly change the answer. For example, people who are asked, "Are you happy with your social life?" report greater satisfaction than those asked, "Are you unhappy with your social life?"');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Confirmation bias: Biased search for information', 'Even a small change in a question''s wording can affect how people search through available information, and hence the conclusions they reach. This was shown using a fictional child custody case. Participants read that Parent A was moderately suitable to be the guardian in multiple ways. Parent B had a mix of salient positive and negative qualities: a close relationship with the child but a job that would take them away for long periods of time. When asked, "Which parent should have custody of the child?" the majority of participants chose Parent B, looking mainly for positive attributes. However, when asked, "Which parent should be denied custody of the child?" they looked for negative attributes and the majority answered that Parent B should be denied custody, implying that Parent A should have custody.', 'Wikipedia: Confirmation bias', 'https://en.wikipedia.org/w/index.php?title=Confirmation_bias&oldid=1370294982', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Even a small change in a question''s wording can affect how people search through available information, and hence the conclusions they reach. This was shown using a fictional child custody case. Participants read that Parent A was moderately suitable to be the guardian in multiple ways. Parent B had a mix of salient positive and negative qualities: a close relationship with the child but a job that would take them away for long periods of time. When asked, "Which parent should have custody of the child?" the majority of participants chose Parent B, looking mainly for positive attributes. However, when asked, "Which parent should be denied custody of the child?" they looked for negative attributes and the majority answered that Parent B should be denied custody, implying that Parent A should have custody.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Confirmation bias: Biased search for information', 'Similar studies have demonstrated how people engage in a biased search for information, but also that this phenomenon may be limited by a preference for genuine diagnostic tests. In an initial experiment, participants rated another person on the introversion–extroversion personality dimension on the basis of an interview. They chose the interview questions from a given list. When the interviewee was introduced as an introvert, the participants chose questions that presumed introversion, such as, "What do you find unpleasant about noisy parties?" When the interviewee was described as extroverted, almost all the questions presumed extroversion, such as, "What would you do to liven up a dull party?" These loaded questions gave the interviewees little or no opportunity to falsify the hypothesis about them. A later version of the experiment gave the participants less presumptive questions to choose from, such as, "Do you shy away from social interactions?" Participants preferred to ask these more diagnostic questions, showing only a weak bias towards positive tests. This pattern, of a main preference for diagnostic tests and a weaker preference for positive tests, has been replicated in other studies.', 'Wikipedia: Confirmation bias', 'https://en.wikipedia.org/w/index.php?title=Confirmation_bias&oldid=1370294982', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Similar studies have demonstrated how people engage in a biased search for information, but also that this phenomenon may be limited by a preference for genuine diagnostic tests. In an initial experiment, participants rated another person on the introversion–extroversion personality dimension on the basis of an interview. They chose the interview questions from a given list. When the interviewee was introduced as an introvert, the participants chose questions that presumed introversion, such as, "What do you find unpleasant about noisy parties?" When the interviewee was described as extroverted, almost all the questions presumed extroversion, such as, "What would you do to liven up a dull party?" These loaded questions gave the interviewees little or no opportunity to falsify the hypothesis about them. A later version of the experiment gave the participants less presumptive questions to choose from, such as, "Do you shy away from social interactions?" Participants preferred to ask these more diagnostic questions, showing only a weak bias towards positive tests. This pattern, of a main preference for diagnostic tests and a weaker preference for positive tests, has been replicated in other studies.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Confirmation bias: Biased search for information', 'Personality traits influence and interact with biased search processes. Individuals vary in their abilities to defend their attitudes from external attacks in relation to selective exposure. Selective exposure occurs when individuals search for information that is consistent, rather than inconsistent, with their personal beliefs. An experiment examined the extent to which individuals could refute arguments that contradicted their personal beliefs. People with high confidence levels more readily seek out contradictory information to their personal position to form an argument. This can take the form of an oppositional news consumption, where individuals seek opposing partisan news in order to counterargue. Individuals with low confidence levels do not seek out contradictory information and prefer information that supports their personal position. People generate and evaluate evidence in arguments that are biased towards their own beliefs and opinions. Heightened confidence levels decrease preference for information that supports individuals'' personal beliefs.', 'Wikipedia: Confirmation bias', 'https://en.wikipedia.org/w/index.php?title=Confirmation_bias&oldid=1370294982', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Personality traits influence and interact with biased search processes. Individuals vary in their abilities to defend their attitudes from external attacks in relation to selective exposure. Selective exposure occurs when individuals search for information that is consistent, rather than inconsistent, with their personal beliefs. An experiment examined the extent to which individuals could refute arguments that contradicted their personal beliefs. People with high confidence levels more readily seek out contradictory information to their personal position to form an argument. This can take the form of an oppositional news consumption, where individuals seek opposing partisan news in order to counterargue. Individuals with low confidence levels do not seek out contradictory information and prefer information that supports their personal position. People generate and evaluate evidence in arguments that are biased towards their own beliefs and opinions. Heightened confidence levels decrease preference for information that supports individuals'' personal beliefs.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Language acquisition', 'Language acquisition is the process by which humans acquire the capacity to perceive and comprehend language. In other words, it is how human beings gain the ability to be aware of language, to understand it, and to produce and use words and sentences to communicate. Language acquisition involves structures, rules, and representation. The capacity to successfully use language requires human beings to acquire a range of tools, including phonology, morphology, syntax, semantics, and an extensive vocabulary. Language can be vocalized as in speech, or manual as in sign. Human language capacity is represented in the brain. Even though human language capacity is finite, one can say and understand an effectively infinite number of sentences, which is based on a syntactic principle called recursion. Evidence suggests that every individual has three recursive mechanisms that allow sentences to go indeterminately. These three mechanisms are: relativization, complementation and coordination. There are two main guiding principles in first-language acquisition: speech perception always precedes speech production, and the gradually evolving system by which a child learns a language is built up one step at a time, beginning with the distinction between individual phonemes.', 'Wikipedia: Language acquisition', 'https://en.wikipedia.org/w/index.php?title=Language_acquisition&oldid=1375526787', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Language acquisition is the process by which humans acquire the capacity to perceive and comprehend language. In other words, it is how human beings gain the ability to be aware of language, to understand it, and to produce and use words and sentences to communicate. Language acquisition involves structures, rules, and representation. The capacity to successfully use language requires human beings to acquire a range of tools, including phonology, morphology, syntax, semantics, and an extensive vocabulary. Language can be vocalized as in speech, or manual as in sign. Human language capacity is represented in the brain. Even though human language capacity is finite, one can say and understand an effectively infinite number of sentences, which is based on a syntactic principle called recursion. Evidence suggests that every individual has three recursive mechanisms that allow sentences to go indeterminately. These three mechanisms are: relativization, complementation and coordination. There are two main guiding principles in first-language acquisition: speech perception always precedes speech production, and the gradually evolving system by which a child learns a language is built up one step at a time, beginning with the distinction between individual phonemes.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Language acquisition', 'For many years, linguists interested in child language acquisition have questioned how language is acquired. Lidz et al. state, "The question of how these structures are acquired, then, is more properly understood as the question of how a learner takes the surface forms in the input and converts them into abstract linguistic rules and representations." Language acquisition usually refers to first-language acquisition. It studies infants'' acquisition of their native language, whether that is a spoken language or a sign language, though it can also refer to bilingual first language acquisition (BFLA), referring to an infant''s simultaneous acquisition of two native languages. This is distinguished from second-language acquisition, which deals with the acquisition (in both children and adults) of additional languages. On top of speech, reading and writing a language with an entirely different script increases the complexities of true foreign language literacy. Language acquisition is one of the quintessential human traits.', 'Wikipedia: Language acquisition', 'https://en.wikipedia.org/w/index.php?title=Language_acquisition&oldid=1375526787', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'For many years, linguists interested in child language acquisition have questioned how language is acquired. Lidz et al. state, "The question of how these structures are acquired, then, is more properly understood as the question of how a learner takes the surface forms in the input and converts them into abstract linguistic rules and representations." Language acquisition usually refers to first-language acquisition. It studies infants'' acquisition of their native language, whether that is a spoken language or a sign language, though it can also refer to bilingual first language acquisition (BFLA), referring to an infant''s simultaneous acquisition of two native languages. This is distinguished from second-language acquisition, which deals with the acquisition (in both children and adults) of additional languages. On top of speech, reading and writing a language with an entirely different script increases the complexities of true foreign language literacy. Language acquisition is one of the quintessential human traits.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Language acquisition: As a typically human phenomenon', 'The capacity to acquire and use language is a key aspect that distinguishes humans from other beings. Although it is difficult to pin down what aspects of language are uniquely human, there are a few design features that can be found in all known forms of human language, but that are missing from forms of animal communication. For example, many animals are able to communicate with each other by signaling to the things around them, but this kind of communication lacks the arbitrariness of human vernaculars (in that there is nothing about the sound of the word "dog" that would hint at its meaning). Other forms of animal communication may utilize arbitrary sounds, but are unable to combine those sounds in different ways to create completely novel messages that can then be automatically understood by another. Hockett called this design feature of human language "productivity". It is crucial to the understanding of human language acquisition that humans are not limited to a finite set of words, but, rather, must be able to understand and utilize a complex system that allows for an infinite number of possible messages. So, while many forms of animal communication exist, they differ from human language in that they have a limited range of vocabulary tokens, and the vocabulary items are not combined syntactically to create phrases.', 'Wikipedia: Language acquisition', 'https://en.wikipedia.org/w/index.php?title=Language_acquisition&oldid=1375526787', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'The capacity to acquire and use language is a key aspect that distinguishes humans from other beings. Although it is difficult to pin down what aspects of language are uniquely human, there are a few design features that can be found in all known forms of human language, but that are missing from forms of animal communication. For example, many animals are able to communicate with each other by signaling to the things around them, but this kind of communication lacks the arbitrariness of human vernaculars (in that there is nothing about the sound of the word "dog" that would hint at its meaning). Other forms of animal communication may utilize arbitrary sounds, but are unable to combine those sounds in different ways to create completely novel messages that can then be automatically understood by another. Hockett called this design feature of human language "productivity". It is crucial to the understanding of human language acquisition that humans are not limited to a finite set of words, but, rather, must be able to understand and utilize a complex system that allows for an infinite number of possible messages. So, while many forms of animal communication exist, they differ from human language in that they have a limited range of vocabulary tokens, and the vocabulary items are not combined syntactically to create phrases.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Language acquisition: As a typically human phenomenon', 'Herbert S. Terrace conducted a study on a chimpanzee known as Nim Chimpsky in an attempt to teach him American Sign Language. This study was an attempt to further research done with a chimpanzee named Washoe, who was reportedly able to acquire American Sign Language. However, upon further inspection, Terrace concluded that both experiments were failures. While Nim was able to acquire signs, he never acquired a knowledge of grammar, and was unable to combine signs in a meaningful way. Researchers noticed that "signs that seemed spontaneous were, in fact, cued by teachers", and not actually productive. When Terrace reviewed Project Washoe, he found similar results. He postulated that there is a fundamental difference between animals and humans in their motivation to learn language; animals, such as in Nim''s case, are motivated only by physical reward, while humans learn language in order to "create a new type of communication".', 'Wikipedia: Language acquisition', 'https://en.wikipedia.org/w/index.php?title=Language_acquisition&oldid=1375526787', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Herbert S. Terrace conducted a study on a chimpanzee known as Nim Chimpsky in an attempt to teach him American Sign Language. This study was an attempt to further research done with a chimpanzee named Washoe, who was reportedly able to acquire American Sign Language. However, upon further inspection, Terrace concluded that both experiments were failures. While Nim was able to acquire signs, he never acquired a knowledge of grammar, and was unable to combine signs in a meaningful way. Researchers noticed that "signs that seemed spontaneous were, in fact, cued by teachers", and not actually productive. When Terrace reviewed Project Washoe, he found similar results. He postulated that there is a fundamental difference between animals and humans in their motivation to learn language; animals, such as in Nim''s case, are motivated only by physical reward, while humans learn language in order to "create a new type of communication".');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Language acquisition: As a typically human phenomenon', 'In another language acquisition study, Jean-Marc-Gaspard Itard attempted to teach Victor of Aveyron, a feral child, how to speak. Victor was able to learn a few words, but ultimately never fully acquired language. A slightly more successful study was done on Genie, another child never introduced to society. She had been entirely isolated for the first thirteen years of her life by her father. Caretakers and researchers attempted to measure her ability to learn a language. She was able to acquire a large vocabulary, but never acquired grammatical knowledge. Researchers concluded that the theory of a critical period was true — Genie was too old to learn how to speak productively, although she was still able to comprehend language.', 'Wikipedia: Language acquisition', 'https://en.wikipedia.org/w/index.php?title=Language_acquisition&oldid=1375526787', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'In another language acquisition study, Jean-Marc-Gaspard Itard attempted to teach Victor of Aveyron, a feral child, how to speak. Victor was able to learn a few words, but ultimately never fully acquired language. A slightly more successful study was done on Genie, another child never introduced to society. She had been entirely isolated for the first thirteen years of her life by her father. Caretakers and researchers attempted to measure her ability to learn a language. She was able to acquire a large vocabulary, but never acquired grammatical knowledge. Researchers concluded that the theory of a critical period was true — Genie was too old to learn how to speak productively, although she was still able to comprehend language.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Language acquisition: General approaches', 'A major debate in understanding language acquisition is how these capacities are picked up by infants from the linguistic input. Input in the linguistic context is defined as "All words, contexts, and other forms of language to which a learner is exposed, relative to acquired proficiency in first or second languages". Nativists such as Chomsky have focused on the hugely complex nature of human grammars, the finiteness and ambiguity of the input that children receive, and the relatively limited cognitive abilities of an infant. From these characteristics, they conclude that the process of language acquisition in infants must be tightly constrained and guided by the biologically given characteristics of the human brain. Otherwise, they argue, it is extremely difficult to explain how children, within the first five years of life, routinely master the complex, largely tacit grammatical rules of their native language. Additionally, the evidence of such rules in their native language is all indirect—adult speech to children cannot encompass all of what children know by the time they have acquired their native language.', 'Wikipedia: Language acquisition', 'https://en.wikipedia.org/w/index.php?title=Language_acquisition&oldid=1375526787', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'A major debate in understanding language acquisition is how these capacities are picked up by infants from the linguistic input. Input in the linguistic context is defined as "All words, contexts, and other forms of language to which a learner is exposed, relative to acquired proficiency in first or second languages". Nativists such as Chomsky have focused on the hugely complex nature of human grammars, the finiteness and ambiguity of the input that children receive, and the relatively limited cognitive abilities of an infant. From these characteristics, they conclude that the process of language acquisition in infants must be tightly constrained and guided by the biologically given characteristics of the human brain. Otherwise, they argue, it is extremely difficult to explain how children, within the first five years of life, routinely master the complex, largely tacit grammatical rules of their native language. Additionally, the evidence of such rules in their native language is all indirect—adult speech to children cannot encompass all of what children know by the time they have acquired their native language.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Language acquisition: General approaches', 'Other scholars, however, have resisted the possibility that infants'' routine success at acquiring the grammar of their native language requires anything more than the forms of learning seen with other cognitive skills, including such mundane motor skills as learning to ride a bike. In particular, there has been resistance to the possibility that human biology includes any form of specialization for language. This conflict is often referred to as the "nature and nurture" debate. Of course, most scholars acknowledge that certain aspects of language acquisition must result from the specific ways in which the human brain is "wired" (a "nature" component, which accounts for the failure of non-human species to acquire human languages) and that certain others are shaped by the particular language environment in which a person is raised (a "nurture" component, which accounts for the fact that humans raised in different societies acquire different languages). The as-yet unresolved question is the extent to which the specific cognitive capacities in the "nature" component are also used outside of language.', 'Wikipedia: Language acquisition', 'https://en.wikipedia.org/w/index.php?title=Language_acquisition&oldid=1375526787', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Other scholars, however, have resisted the possibility that infants'' routine success at acquiring the grammar of their native language requires anything more than the forms of learning seen with other cognitive skills, including such mundane motor skills as learning to ride a bike. In particular, there has been resistance to the possibility that human biology includes any form of specialization for language. This conflict is often referred to as the "nature and nurture" debate. Of course, most scholars acknowledge that certain aspects of language acquisition must result from the specific ways in which the human brain is "wired" (a "nature" component, which accounts for the failure of non-human species to acquire human languages) and that certain others are shaped by the particular language environment in which a person is raised (a "nurture" component, which accounts for the fact that humans raised in different societies acquire different languages). The as-yet unresolved question is the extent to which the specific cognitive capacities in the "nature" component are also used outside of language.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Language acquisition: Emergentism', 'Emergentist theories, such as Brian MacWhinney''s competition model, posit that language acquisition is a cognitive process that emerges from the interaction of biological pressures and the environment. According to these theories, neither nature nor nurture alone is sufficient to trigger language learning; both of these influences must work together in order to allow children to acquire a language. The proponents of these theories argue that general cognitive processes subserve language acquisition and that the result of these processes is language-specific phenomena, such as word learning and grammar acquisition. The findings of many empirical studies support the predictions of these theories, suggesting that language acquisition is a more complex process than many have proposed.', 'Wikipedia: Language acquisition', 'https://en.wikipedia.org/w/index.php?title=Language_acquisition&oldid=1375526787', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Emergentist theories, such as Brian MacWhinney''s competition model, posit that language acquisition is a cognitive process that emerges from the interaction of biological pressures and the environment. According to these theories, neither nature nor nurture alone is sufficient to trigger language learning; both of these influences must work together in order to allow children to acquire a language. The proponents of these theories argue that general cognitive processes subserve language acquisition and that the result of these processes is language-specific phenomena, such as word learning and grammar acquisition. The findings of many empirical studies support the predictions of these theories, suggesting that language acquisition is a more complex process than many have proposed.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Broca''s area', 'Broca''s area, or the Broca area (, also UK:, US: ), is a region in the frontal lobe of the dominant hemisphere, usually the left, of the brain with functions linked to speech production. Language processing has been linked to Broca''s area since Pierre Paul Broca reported impairments in two patients. They had lost the ability to speak after injury to the posterior inferior frontal gyrus (pars triangularis) (BA45) of the brain. Since then, the approximate region he identified has become known as Broca''s area, and the deficit in language production as Broca''s aphasia, also called expressive aphasia. Broca''s area is now typically defined in terms of the pars opercularis and pars triangularis of the inferior frontal gyrus, represented in Brodmann''s cytoarchitectonic map as Brodmann area 44 and Brodmann area 45 of the dominant hemisphere. Functional magnetic resonance imaging (fMRI) has shown language processing to also involve the third part of the inferior frontal gyrus the pars orbitalis, as well as the ventral part of BA6 and these are now often included in a larger area called Broca''s region.', 'Wikipedia: Broca''s area', 'https://en.wikipedia.org/w/index.php?title=Broca''s_area&oldid=1369046970', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Broca''s area, or the Broca area (, also UK:, US: ), is a region in the frontal lobe of the dominant hemisphere, usually the left, of the brain with functions linked to speech production. Language processing has been linked to Broca''s area since Pierre Paul Broca reported impairments in two patients. They had lost the ability to speak after injury to the posterior inferior frontal gyrus (pars triangularis) (BA45) of the brain. Since then, the approximate region he identified has become known as Broca''s area, and the deficit in language production as Broca''s aphasia, also called expressive aphasia. Broca''s area is now typically defined in terms of the pars opercularis and pars triangularis of the inferior frontal gyrus, represented in Brodmann''s cytoarchitectonic map as Brodmann area 44 and Brodmann area 45 of the dominant hemisphere. Functional magnetic resonance imaging (fMRI) has shown language processing to also involve the third part of the inferior frontal gyrus the pars orbitalis, as well as the ventral part of BA6 and these are now often included in a larger area called Broca''s region.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Broca''s area', 'Studies of chronic aphasia have implicated an essential role of Broca''s area in various speech and language functions. Further, fMRI studies have also identified activation patterns in Broca''s area associated with various language tasks. However, slow destruction of Broca''s area by brain tumors can leave speech relatively intact, suggesting its functions can shift to nearby areas in the brain.', 'Wikipedia: Broca''s area', 'https://en.wikipedia.org/w/index.php?title=Broca''s_area&oldid=1369046970', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Studies of chronic aphasia have implicated an essential role of Broca''s area in various speech and language functions. Further, fMRI studies have also identified activation patterns in Broca''s area associated with various language tasks. However, slow destruction of Broca''s area by brain tumors can leave speech relatively intact, suggesting its functions can shift to nearby areas in the brain.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Broca''s area: Structure', 'Broca''s area is often identified by visual inspection of the topography of the brain either by macrostructural landmarks such as sulci or by the specification of coordinates in a particular reference space. The currently used Talairach and Tournoux atlas projects Brodmann''s cytoarchitectonic map onto a template brain. Because Brodmann''s parcelation was based on subjective visual inspection of cytoarchitectonic borders and also Brodmann analyzed only one hemisphere of one brain, the result is imprecise. Further, because of considerable variability across brains in terms of shape, size, and position relative to sulcal and gyral structure, a resulting localization precision is limited. Nevertheless, Broca''s area in the left hemisphere and its homologue in the right hemisphere are designations usually used to refer to the triangular part of inferior frontal gyrus (PTr) and the opercular part of inferior frontal gyrus (POp). The PTr and POp are defined by structural landmarks that only probabilistically divide the inferior frontal gyrus into anterior and posterior cytoarchitectonic areas of 45 and 44, respectively, by Brodmann''s classification scheme. Area 45 receives more afferent connections from the prefrontal cortex, the superior temporal gyrus, and the superior temporal sulcus, compared to area 44, which tends to receive more afferent connections from motor, somatosensory, and inferior parietal regions.', 'Wikipedia: Broca''s area', 'https://en.wikipedia.org/w/index.php?title=Broca''s_area&oldid=1369046970', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Broca''s area is often identified by visual inspection of the topography of the brain either by macrostructural landmarks such as sulci or by the specification of coordinates in a particular reference space. The currently used Talairach and Tournoux atlas projects Brodmann''s cytoarchitectonic map onto a template brain. Because Brodmann''s parcelation was based on subjective visual inspection of cytoarchitectonic borders and also Brodmann analyzed only one hemisphere of one brain, the result is imprecise. Further, because of considerable variability across brains in terms of shape, size, and position relative to sulcal and gyral structure, a resulting localization precision is limited. Nevertheless, Broca''s area in the left hemisphere and its homologue in the right hemisphere are designations usually used to refer to the triangular part of inferior frontal gyrus (PTr) and the opercular part of inferior frontal gyrus (POp). The PTr and POp are defined by structural landmarks that only probabilistically divide the inferior frontal gyrus into anterior and posterior cytoarchitectonic areas of 45 and 44, respectively, by Brodmann''s classification scheme. Area 45 receives more afferent connections from the prefrontal cortex, the superior temporal gyrus, and the superior temporal sulcus, compared to area 44, which tends to receive more afferent connections from motor, somatosensory, and inferior parietal regions.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Broca''s area: Structure', 'The differences between area 45 and 44 in cytoarchitecture and in connectivity suggest that these areas might perform different functions. Indeed, recent neuroimaging studies have shown that the PTr and Pop, corresponding to areas 45 and 44, respectively, play different functional roles in the human with respect to language comprehension and action recognition/understanding. Brodmann area 44 (BA44) is strongly connected to premotor and supplementary motor regions, and is therefore involved in phonological processing, syntactic structure building, and the motor sequencing of speech production. Researchers also highlight that BA44 is highly engaged in hierarchical processing, the ability to organize and understand multi-level structured information. Lesions to BA44 have been associated with impairments in grammatical morphology, reduced fluency of speech, and articulation planning. Brodmann area 45 (BA45) is often associated with controlled semantic retrieval and top-down processing during language comprehension. Neuroimaging studies found greater BA45 activation during tasks that require choosing among multiple words of the same meaning. In addition, cytoarchitecturally, because BA45 receives stronger input from temporoparietal areas involved in semantic processing, it has a more developed granular layer (layer IV) than BA44.', 'Wikipedia: Broca''s area', 'https://en.wikipedia.org/w/index.php?title=Broca''s_area&oldid=1369046970', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'The differences between area 45 and 44 in cytoarchitecture and in connectivity suggest that these areas might perform different functions. Indeed, recent neuroimaging studies have shown that the PTr and Pop, corresponding to areas 45 and 44, respectively, play different functional roles in the human with respect to language comprehension and action recognition/understanding. Brodmann area 44 (BA44) is strongly connected to premotor and supplementary motor regions, and is therefore involved in phonological processing, syntactic structure building, and the motor sequencing of speech production. Researchers also highlight that BA44 is highly engaged in hierarchical processing, the ability to organize and understand multi-level structured information. Lesions to BA44 have been associated with impairments in grammatical morphology, reduced fluency of speech, and articulation planning. Brodmann area 45 (BA45) is often associated with controlled semantic retrieval and top-down processing during language comprehension. Neuroimaging studies found greater BA45 activation during tasks that require choosing among multiple words of the same meaning. In addition, cytoarchitecturally, because BA45 receives stronger input from temporoparietal areas involved in semantic processing, it has a more developed granular layer (layer IV) than BA44.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Broca''s area: Language comprehension', 'For a long time, it was assumed that the role of Broca''s area was more devoted to language production than language comprehension. However, there is evidence to demonstrate that Broca''s area also plays a significant role in language comprehension. Patients with lesions in Broca''s area who exhibit agrammatical speech production also show inability to use syntactic information to determine the meaning of sentences. Also, a number of neuroimaging studies have implicated an involvement of Broca''s area, particularly of the pars opercularis of the left inferior frontal gyrus, during the processing of complex sentences. Further, functional magnetic resonance imaging (fMRI) experiments have shown that highly ambiguous sentences result in a more activated inferior frontal gyrus. Therefore, the activity level in the inferior frontal gyrus and the level of lexical ambiguity are directly proportional to each other, because of the increased retrieval demands associated with highly ambiguous content.', 'Wikipedia: Broca''s area', 'https://en.wikipedia.org/w/index.php?title=Broca''s_area&oldid=1369046970', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'For a long time, it was assumed that the role of Broca''s area was more devoted to language production than language comprehension. However, there is evidence to demonstrate that Broca''s area also plays a significant role in language comprehension. Patients with lesions in Broca''s area who exhibit agrammatical speech production also show inability to use syntactic information to determine the meaning of sentences. Also, a number of neuroimaging studies have implicated an involvement of Broca''s area, particularly of the pars opercularis of the left inferior frontal gyrus, during the processing of complex sentences. Further, functional magnetic resonance imaging (fMRI) experiments have shown that highly ambiguous sentences result in a more activated inferior frontal gyrus. Therefore, the activity level in the inferior frontal gyrus and the level of lexical ambiguity are directly proportional to each other, because of the increased retrieval demands associated with highly ambiguous content.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Broca''s area: Language comprehension', 'There is also specialization for particular aspects of comprehension within Broca''s area. Work by Devlin et al. (2003) showed in a repetitive transcranial magnetic stimulation (rTMS) study that there was an increase in reaction times when performing a semantic task under rTMS aimed at the pars triangularis (situated in the anterior part of Broca''s area). The increase in reaction times is indicative that that particular area is responsible for processing that cognitive function. Disrupting these areas via TMS disrupts computations performed in the areas leading to an increase in time needed to perform the computations (reflected in reaction times). Later work by Nixon et al. (2004) showed that when the pars opercularis (situated in the posterior part of Broca''s area) was stimulated under rTMS there was an increase in reaction times in a phonological task. Gough et al. (2005) performed an experiment combining elements of these previous works in which both phonological and semantic tasks were performed with rTMS stimulation directed at either the anterior or the posterior part of Broca''s area. The results from this experiment conclusively distinguished anatomical specialization within Broca''s area for different components of language comprehension. Here the results showed that under rTMS stimulation:', 'Wikipedia: Broca''s area', 'https://en.wikipedia.org/w/index.php?title=Broca''s_area&oldid=1369046970', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'There is also specialization for particular aspects of comprehension within Broca''s area. Work by Devlin et al. (2003) showed in a repetitive transcranial magnetic stimulation (rTMS) study that there was an increase in reaction times when performing a semantic task under rTMS aimed at the pars triangularis (situated in the anterior part of Broca''s area). The increase in reaction times is indicative that that particular area is responsible for processing that cognitive function. Disrupting these areas via TMS disrupts computations performed in the areas leading to an increase in time needed to perform the computations (reflected in reaction times). Later work by Nixon et al. (2004) showed that when the pars opercularis (situated in the posterior part of Broca''s area) was stimulated under rTMS there was an increase in reaction times in a phonological task. Gough et al. (2005) performed an experiment combining elements of these previous works in which both phonological and semantic tasks were performed with rTMS stimulation directed at either the anterior or the posterior part of Broca''s area. The results from this experiment conclusively distinguished anatomical specialization within Broca''s area for different components of language comprehension. Here the results showed that under rTMS stimulation:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Broca''s area: Language comprehension', 'Semantic tasks only showed a decrease in reaction times when stimulation was aimed at the anterior part of Broca''s area (where a decrease of 10% (50 ms) was seen compared to a no-TMS control group) Phonological tasks showed a decrease in reaction times when stimulation was aimed at the posterior part of Broca''s area (where a decrease of 6% (30 ms) was seen compared to control) To summarise, the work above shows anatomical specialisation in Broca''s area for language comprehension, with the anterior part of Broca''s area responsible for understanding the meaning of words (semantics) and the posterior part of Broca''s area responsible for understanding how words sound (phonology).', 'Wikipedia: Broca''s area', 'https://en.wikipedia.org/w/index.php?title=Broca''s_area&oldid=1369046970', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Semantic tasks only showed a decrease in reaction times when stimulation was aimed at the anterior part of Broca''s area (where a decrease of 10% (50 ms) was seen compared to a no-TMS control group) Phonological tasks showed a decrease in reaction times when stimulation was aimed at the posterior part of Broca''s area (where a decrease of 6% (30 ms) was seen compared to control) To summarise, the work above shows anatomical specialisation in Broca''s area for language comprehension, with the anterior part of Broca''s area responsible for understanding the meaning of words (semantics) and the posterior part of Broca''s area responsible for understanding how words sound (phonology).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cognition-language', 'Broca''s area: Action recognition and production', 'Experiments have indicated that Broca''s area is involved in various cognitive and perceptual tasks. One important contribution of Brodmann''s area 44 is also found in the motor-related processes. Observation of meaningful hand shadows resembling moving animals activates frontal language area, demonstrating that Broca''s area indeed plays a role in interpreting action of others. An activation of BA 44 was also reported during execution of grasping and manipulation.', 'Wikipedia: Broca''s area', 'https://en.wikipedia.org/w/index.php?title=Broca''s_area&oldid=1369046970', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cognition-language' and body = 'Experiments have indicated that Broca''s area is involved in various cognitive and perceptual tasks. One important contribution of Brodmann''s area 44 is also found in the motor-related processes. Observation of meaningful hand shadows resembling moving animals activates frontal language area, demonstrating that Broca''s area indeed plays a role in interpreting action of others. An activation of BA 44 was also reported during execution of grasping and manipulation.');
commit;
